from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.ai.documentintelligence.models import ContentFormat
from azure.core.credentials import AzureKeyCredential
import os

def extract_key_value_pairs_from_document(document_path: str) -> dict[str, str]:
    """
    Extracts key-value pairs from a form-like document using Azure Document Intelligence.
    """
    endpoint = os.environ["AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT"]
    key = os.environ["AZURE_DOCUMENT_INTELLIGENCE_KEY"]

    document_intelligence_client = DocumentIntelligenceClient(
        endpoint=endpoint, credential=AzureKeyCredential(key)
    )

    # Use the 'prebuilt-document' model for general document processing,
    # which includes key-value pair extraction if applicable.
    # For more specific form processing, a custom model or prebuilt-invoice/receipt could be used.
    model_id = "prebuilt-document" 

    with open(document_path, "rb") as f:
        poller = document_intelligence_client.begin_analyze_document(
            model_id=model_id,
            analyze_request=f,
            content_type="application/pdf" # Adjust content_type based on the actual document type (e.g., image/jpeg)
        )
        result = poller.result()

    extracted_data = {}
    if result.documents:
        # Assuming the first document contains the relevant data
        for document in result.documents:
            if document.fields:
                for field_name, field_value in document.fields.items():
                    if field_value.value is not None:
                        extracted_data[field_name] = str(field_value.value)
            # Also check for directly extracted key-value pairs if the model supports it explicitly
            if document.key_value_pairs:
                for kv_pair in document.key_value_pairs:
                    if kv_pair.key and kv_pair.value:
                        extracted_data[kv_pair.key.content] = kv_pair.value.content

    return extracted_data
